using UnityEditor; using UnityEditor.Animations; using UnityEngine; using System.Linq; namespace AuraFarming.Editor { public static class CatAdditionalAnimationsBuilder { const string D="Assets/_Project/Animations/Cats/"; const string CP=D+"BaseCat.controller"; [MenuItem("Aura Farming/Cats/Sync All Winner Animations")] public static void Sync(){var c=AssetDatabase.LoadAssetAtPath<AnimatorController>(CP);if(c==null){Debug.LogError("Missing BaseCat.controller");return;} var sm=c.layers[0].stateMachine; Add(c,sm,"Win_StinkyDance","PlayStinkyDance",3f,18f);Add(c,sm,"Win_AnimePose","PlayAnimePose",2.8f,55f);Add(c,sm,"Win_SigmaLook","PlaySigmaLook",2.5f,12f);Add(c,sm,"Win_Silence","PlaySilence",2.3f,20f);Add(c,sm,"Win_Snap","PlaySnap",2.2f,42f);AssetDatabase.SaveAssets();AssetDatabase.Refresh();} static void Add(AnimatorController c,AnimatorStateMachine sm,string n,string tr,float end,float peak){var path=D+n+".anim";var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(path);if(clip==null){clip=new AnimationClip{name=n,frameRate=30f,wrapMode=WrapMode.Once};Curve(clip,"Body","localEulerAnglesRaw.z",0,0,.35f,-peak,.85f,peak,1.45f,peak,2.15f,peak,end,0);Curve(clip,"ArmLeft","localEulerAnglesRaw.z",0,0,.85f,-peak*2f,1.45f,-peak*2f,2.15f,-peak*2f,end,0);Curve(clip,"ArmRight","localEulerAnglesRaw.z",0,0,.85f,peak*2f,1.45f,peak*2f,2.15f,peak*2f,end,0);Curve(clip,"Aura","m_LocalScale.x",0,1,.85f,1.3f,1.45f,1.5f,2.15f,1.5f,end,1);Curve(clip,"Aura","m_LocalScale.y",0,1,.85f,1.3f,1.45f,1.5f,2.15f,1.5f,end,1);Curve(clip,"Flash","m_IsActive",0,0,1.43f,0,1.47f,1,1.65f,0,end,0);AssetDatabase.CreateAsset(clip,path);}if(!c.parameters.Any(x=>x.name==tr))c.AddParameter(tr,AnimatorControllerParameterType.Trigger);var st=sm.states.FirstOrDefault(x=>x.state.name==n).state;if(st==null)st=sm.AddState(n);st.motion=clip;var idle=sm.defaultState;if(!idle.transitions.Any(x=>x.destinationState==st)){var t=idle.AddTransition(st);t.hasExitTime=false;t.duration=.05f;t.AddCondition(AnimatorConditionMode.If,0,tr);}if(!st.transitions.Any(x=>x.destinationState==idle)){var t=st.AddTransition(idle);t.hasExitTime=true;t.exitTime=1f;t.duration=.08f;}}static void Curve(AnimationClip c,string p,string prop,params float[] v){var k=new Keyframe[v.Length/2];for(int i=0;i<k.Length;i++)k[i]=new Keyframe(v[i*2],v[i*2+1]);c.SetCurve(p,typeof(Transform),prop,new AnimationCurve(k));}}}